<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Signatories {
 public static function create(\PDO $p,int $u,int $org,int $user,string $name,string $position,int $document,int $version):int {
  \EPejabat\Modules\Training\ExtendedMigrations::require($p);if(!Authorization::super($p,$u))Authorization::require($p,$u,'training.signatories.manage',$org);$profile=Database::query($p,'SELECT u.id,s.organisation_id FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.id=? AND u.is_active=1',[$user])->fetch();if(!$profile||!Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$org,$profile['organisation_id']])->fetchColumn())throw new \RuntimeException('Signatory di luar scope.');$v=Documents::version($p,$u,$document,$version);$d=Documents::access($p,$u,$document,true);if((int)$d['organisation_id']!==$org||$v['mime']!=='image/jpeg')throw new \RuntimeException('Signature mesti JPEG pada scope sama.');Database::query($p,'INSERT INTO core_signatories(organisation_id,user_id,name,position_title,signature_document_id,signature_version,created_by) VALUES(?,?,?,?,?,?,?)',[$org,$user,Core::text($name),Core::text($position),$document,$version,$u]);$id=(int)$p->lastInsertId();Audit::record($p,'signatory.created',$u,$org,(string)$id,'training');return $id;
 }
 public static function snapshot(\PDO $p,int $u,int $id,int $org):array {$s=Database::query($p,'SELECT s.*,o.name AS organisation_name FROM core_signatories s JOIN organisations o ON o.id=s.organisation_id WHERE s.id=? AND s.is_active=1 AND o.is_active=1',[$id])->fetch();if(!$s||!Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$s['organisation_id'],$org])->fetchColumn())throw new \RuntimeException('Signatory scope tidak sah.');if(!Authorization::super($p,$u))Authorization::require($p,$u,'training.signatories.manage',(int)$s['organisation_id']);$v=Documents::version($p,$u,(int)$s['signature_document_id'],(int)$s['signature_version']);return ['id'=>$s['id'],'name'=>$s['name'],'position'=>$s['position_title'],'organisation'=>$s['organisation_name'],'document_id'=>$s['signature_document_id'],'version'=>$s['signature_version'],'checksum'=>$v['checksum'],'finalised_at'=>gmdate('c')];}
 public static function deactivate(\PDO $p,int $u,int $id):void {$s=Database::query($p,'SELECT * FROM core_signatories WHERE id=?',[$id])->fetch();if(!$s)throw new \RuntimeException('Signatory tidak wujud.');if(!Authorization::super($p,$u))Authorization::require($p,$u,'training.signatories.manage',(int)$s['organisation_id']);Database::query($p,'UPDATE core_signatories SET is_active=0 WHERE id=?',[$id]);Audit::record($p,'signatory.deactivated',$u,(int)$s['organisation_id'],(string)$id,'training');}
}
